"""Tests for E-229-08: defensive positioning bundle assembler.

Covers AC-1 through AC-8:
* AC-1: 4-page assembly order + content per page; writes to
  `data/reports/{slug}/index.html`
* AC-2: 2 landscape + 1 portrait named @page directives
* AC-3: bundle generated by `generate_report(public_id)` per the
  existing pattern (E-228 lifecycle preserved)
* AC-4 + AC-4a: consistent coverage cue across pages + snapshot
  persistence via `bundle_snapshot.json` sidecar (re-render reads
  snapshot, ignores live DB freshness)
* AC-5: zero-coverage degradation still produces 4 pages
* AC-6 (a-e): cross-AC smoke tests + AC-6(e) re-render persistence
* AC-7: LLM render-time threading per flagged batter
* AC-8: LLM ephemerality — no INSERT/UPDATE against positioning tables
"""

from __future__ import annotations

import json
import re
import sqlite3
from pathlib import Path
from unittest.mock import patch

import pytest

import src.reports.positioning_bundle as positioning_bundle
from src.reports.positioning import COVERED_POSITIONS
from src.reports.positioning_bundle import generate_positioning_bundle
from tests.conftest import load_real_schema


