# AC-5 / AC-6 (c) -- Zero-coverage degradation
# ---------------------------------------------------------------------------


class TestZeroCoverage:
    def test_zero_bip_team_still_produces_all_four_pages(self, conn):
        """AC-5: when team has 0 BIPs total, the bundle still produces
        all four pages — none of the sections is silently dropped."""
        # No aggregates seeded (zero coverage everywhere).
        _seed_player(conn, "p1", "Hank", "Ramirez")
        _seed_roster(conn, "p1", "7")
        conn.commit()

        html = generate_positioning_bundle(
            conn, "opp-bears", _SEASON,
            opponent_name="Opp Bears",
            through_date="Apr 12", game_count=12,
        )
        # All three section wrappers still appear.
        assert "positioning-call-sheet" in html
        assert "positioning-prep-page" in html
        assert "positioning-cards-sheet" in html

    def test_zero_bip_renders_zero_coverage_message(self, conn):
        """AC-5: call sheet + prep page render the zero-coverage
        variant in place of the matrix / field."""
        _seed_player(conn, "p1", "Hank", "Ramirez")
        _seed_roster(conn, "p1", "7")
        conn.commit()

        html = generate_positioning_bundle(
            conn, "opp-bears", _SEASON,
            opponent_name="Opp Bears",
            through_date="Apr 12", game_count=12,
        )
        assert "Not enough spray data" in html

    def test_low_bip_team_below_15_threshold_renders_zero_coverage(self, conn):
        """AC-5: when team aggregate bip_count < 15 the call sheet +
        prep page still degrade to zero-coverage. (Cards use the same
        15-BIP threshold per E-229-03 AC-9.)"""
        _seed_aggregates(conn, bip_count=10)
        _seed_player(conn, "p1", "Hank", "Ramirez")
        _seed_roster(conn, "p1", "7")
        for p in COVERED_POSITIONS:
            _seed_batter_row(
                conn, player_id="p1", position=p, bip_count=10,
            )
        conn.commit()

        html = generate_positioning_bundle(
            conn, "opp-bears", _SEASON,
            opponent_name="Opp Bears",
            through_date="Apr 12", game_count=12,
        )
        assert "positioning-call-sheet" in html
        assert "positioning-prep-page" in html
        assert "positioning-cards-sheet" in html


# ---------------------------------------------------------------------------
# AC-7 -- LLM render-time threading
# ---------------------------------------------------------------------------


class TestLLMRenderTimeThreading:
    def test_llm_unavailable_skips_rationales_silently(self, conn, monkeypatch):
        """AC-7: when is_llm_available() returns False, the bundle
        renders without rationale lines for any batter, INFO log only."""
        _seed_full_opponent(conn)
        # Strip OPENROUTER_API_KEY so is_llm_available() returns False.
        monkeypatch.delenv("OPENROUTER_API_KEY", raising=False)

        with patch(
            "src.reports.positioning_bundle.generate_rationale"
        ) as mock_gen:
            html = generate_positioning_bundle(
                conn, "opp-bears", _SEASON,
                opponent_name="Opp Bears",
                through_date="Apr 12", game_count=12,
            )
        # The shortcut in _build_rationales bails before any
        # generate_rationale call when is_llm_available is False.
        mock_gen.assert_not_called()
        # Bundle still produced, no crash.
        assert "positioning-call-sheet" in html

    def test_llm_available_calls_generate_rationale_per_flagged_batter(
        self, conn, monkeypatch,
    ):
        """AC-7: for each flagged batter the assembler calls
        `generate_rationale(batter_row, aggregate_row, batter_metadata)`."""
        _seed_full_opponent(conn)
        # p1 + p2 are flagged (3 flagged (player, position) rows across
        # them: p1@LF, p2@LF, p2@RF). The assembler dedup's by player_id
        # — so the call count should be 2.
        monkeypatch.setenv("OPENROUTER_API_KEY", "sk-test")

        with patch(
            "src.reports.positioning_bundle.generate_rationale",
            return_value=None,
        ) as mock_gen:
            html = generate_positioning_bundle(
                conn, "opp-bears", _SEASON,
                opponent_name="Opp Bears",
                through_date="Apr 12", game_count=12,
            )
        assert mock_gen.call_count == 2  # p1 + p2 (deduped by player_id)
        assert "positioning-call-sheet" in html

    def test_llm_rationale_threaded_into_call_sheet_note(
        self, conn, monkeypatch,
    ):
        """AC-7: a rationale returned by the LLM appears in the
        rendered call-sheet NOTE cell for the flagged batter."""
        _seed_full_opponent(conn)
        monkeypatch.setenv("OPENROUTER_API_KEY", "sk-test")

        # Return distinct rationales per player so we can verify
        # threading.
        def fake_rationale(batter_row, aggregate_row, batter_metadata):
            if batter_metadata["last_name"] == "Ramirez":
                return "Ramirez prefers Zone A on inside fastballs early counts."
            if batter_metadata["last_name"] == "Davis":
                return "Davis pulls 11 grounders to Zone B against breaking pitches."
            return None

        with patch(
            "src.reports.positioning_bundle.generate_rationale",
            side_effect=fake_rationale,
        ):
            html = generate_positioning_bundle(
                conn, "opp-bears", _SEASON,
                opponent_name="Opp Bears",
                through_date="Apr 12", game_count=12,
            )
        # Both rationales appear in the rendered HTML.
        assert "Ramirez prefers Zone A on inside fastballs early counts." in html
        assert "Davis pulls 11 grounders to Zone B against breaking pitches." in html

    def test_llm_exception_is_non_fatal(self, conn, monkeypatch):
        """AC-7: an exception raised by generate_rationale mid-call is
        caught at the per-batter level; bundle still renders for the
        rest of the lineup."""
        _seed_full_opponent(conn)
        monkeypatch.setenv("OPENROUTER_API_KEY", "sk-test")

        with patch(
            "src.reports.positioning_bundle.generate_rationale",
            side_effect=RuntimeError("synthetic LLM crash"),
        ):
            html = generate_positioning_bundle(
                conn, "opp-bears", _SEASON,
                opponent_name="Opp Bears",
                through_date="Apr 12", game_count=12,
            )
        # Bundle still produced; no rationale text in it.
        assert "positioning-call-sheet" in html

    def test_llm_returns_none_for_one_batter_others_still_render(
        self, conn, monkeypatch,
    ):
        """AC-7: a per-batter None return drops the rationale for that
        batter but the others' rationales still appear."""
        _seed_full_opponent(conn)
        monkeypatch.setenv("OPENROUTER_API_KEY", "sk-test")

        def fake_rationale(batter_row, aggregate_row, batter_metadata):
            if batter_metadata["last_name"] == "Ramirez":
                return None  # validation rejection
            return "Davis has 11 left-side pulled balls this season clearly."

        with patch(
            "src.reports.positioning_bundle.generate_rationale",
            side_effect=fake_rationale,
        ):
            html = generate_positioning_bundle(
                conn, "opp-bears", _SEASON,
                opponent_name="Opp Bears",
                through_date="Apr 12", game_count=12,
            )
        # Davis's rationale is in the HTML; Ramirez's is dropped.
        assert "Davis has 11 left-side pulled balls" in html


# ---------------------------------------------------------------------------
# AC-8 -- LLM ephemerality (no DB writes)
# ---------------------------------------------------------------------------


class TestLLMEphemerality:
    """AC-8: a test asserts no INSERT/UPDATE statements are issued
    against `batter_positioning` or `team_position_aggregate` during
    the LLM rationale path."""

    SOURCE_PATH = Path(positioning_bundle.__file__)

    def test_module_source_has_no_insert_or_update_on_positioning_tables(
        self,
    ):
        """Grep AC: the assembler module emits zero INSERT/UPDATE
        statements against positioning tables. (SELECT is fine — the
        assembler reads to build context.)"""
        text = self.SOURCE_PATH.read_text()
        forbidden_patterns = (
            r"INSERT\s+INTO\s+batter_positioning",
            r"UPDATE\s+batter_positioning",
            r"INSERT\s+INTO\s+team_position_aggregate",
            r"UPDATE\s+team_position_aggregate",
        )
        for pat in forbidden_patterns:
            assert not re.search(pat, text, re.IGNORECASE), (
                f"positioning_bundle.py must not write to positioning "
                f"tables (AC-8); found pattern {pat!r}"
            )

    def test_runtime_no_writes_during_llm_path(self, conn, monkeypatch):
        """Runtime AC-8: count INSERT/UPDATE statements against the
        positioning tables before and after a bundle render with the
        LLM enabled — the delta MUST be zero."""
        _seed_full_opponent(conn)
        monkeypatch.setenv("OPENROUTER_API_KEY", "sk-test")

        def count_rows():
            bp = conn.execute(
                "SELECT COUNT(*) FROM batter_positioning"
            ).fetchone()[0]
            agg = conn.execute(
                "SELECT COUNT(*) FROM team_position_aggregate"
            ).fetchone()[0]
            return bp, agg

        before = count_rows()
        with patch(
            "src.reports.positioning_bundle.generate_rationale",
            return_value=(
                "Pulls Zone B grounders early in counts against fastballs "
                "this season cleanly."
            ),
        ):
            generate_positioning_bundle(
                conn, "opp-bears", _SEASON,
                opponent_name="Opp Bears",
                through_date="Apr 12", game_count=12,
            )
        after = count_rows()
        assert after == before, (
            f"AC-8 violated: row counts changed during LLM path. "
            f"before={before} after={after}"
        )


