# R2: AC-1 / AC-3 / AC-4a / AC-6(e) -- bundle persistence + re-render
# ---------------------------------------------------------------------------
#
# The R1 deliverable shipped a standalone assembler function only. R2
# adds the integration into generate_report() via three helpers in
# generator.py:
#   * _write_positioning_bundle()   -- writes index.html + snapshot
#   * regenerate_positioning_bundle() -- re-renders from snapshot
#   * _format_through_date()         -- ISO date -> "Mon Day"
# Storage shape per AC-4a: file metadata sidecar at
# data/reports/{slug}/bundle_snapshot.json (option (b) of the three
# listed in AC-4a).


class _NoCloseConn:
    """Sqlite3-Connection proxy that no-ops .close() so test fixture
    lifetime is preserved across multiple generator-side get_connection()
    calls (each wrapped in `with closing(get_connection())`)."""

    def __init__(self, c):
        self._c = c

    def __getattr__(self, name):
        # Delegate everything (execute, executemany, commit, etc.) to
        # the underlying sqlite3.Connection.
        return getattr(self._c, name)

    def close(self):
        pass


