class TestRegenerateBundleFromSnapshot:
    """AC-6(e): the coverage-cue text survives a re-render even when
    the underlying DB freshness has advanced (the snapshot is the
    source of truth, not the live DB)."""

    def test_regenerate_uses_snapshot_not_live_freshness(
        self, conn, tmp_path, monkeypatch,
    ):
        _seed_full_opponent(conn)
        import src.reports.generator as gen
        reports_dir = tmp_path / "data" / "reports"
        monkeypatch.setattr(gen, "_REPO_ROOT", tmp_path)
        monkeypatch.setattr(gen, "_REPORTS_DIR", reports_dir)
        monkeypatch.setattr(
            gen, "get_connection", lambda: _NoCloseConn(conn),
        )

        # First generation: snapshot captures Apr 12 / 12 games.
        gen._write_positioning_bundle(
            slug="slug-rerun",
            team_id=1,
            public_id="opp-bears",
            season_id=_SEASON,
            opponent_name="Opp Bears",
            freshness_date="2026-04-12",
            game_count=12,
        )
        bundle_path = reports_dir / "slug-rerun" / "index.html"
        html_v1 = bundle_path.read_text(encoding="utf-8")
        assert "Through Apr 12 (12 games)" in html_v1

        # Mutate the DB to mimic later scouting -- if the re-render
        # consulted live data the cue would change. Bumping aggregate
        # counts is enough to prove the re-render relies on snapshot,
        # not freshness query.
        for p in COVERED_POSITIONS:
            conn.execute(
                "UPDATE team_position_aggregate SET bip_count = 999 "
                "WHERE position = ? AND team_id = 1",
                (p,),
            )
        conn.commit()

        # Regenerate from the persisted snapshot.
        rel_path = gen.regenerate_positioning_bundle("slug-rerun")
        assert rel_path.endswith("slug-rerun/index.html")
        html_v2 = bundle_path.read_text(encoding="utf-8")

        # AC-6(e) invariance: the coverage cue text is present in
        # both renders with the same count. (The body HTML may differ
        # slightly because cards reflect the bumped bip_count, but the
        # header cue is fed from the snapshot kwargs, which haven't
        # changed.)
        assert "Through Apr 12 (12 games)" in html_v2
        v1_cue_count = html_v1.count("Through Apr 12 (12 games)")
        v2_cue_count = html_v2.count("Through Apr 12 (12 games)")
        assert v1_cue_count == v2_cue_count

    def test_regenerate_raises_when_snapshot_missing(
        self, tmp_path, monkeypatch,
    ):
        import src.reports.generator as gen
        reports_dir = tmp_path / "data" / "reports"
        monkeypatch.setattr(gen, "_REPO_ROOT", tmp_path)
        monkeypatch.setattr(gen, "_REPORTS_DIR", reports_dir)
        with pytest.raises(FileNotFoundError, match="No bundle snapshot"):
            gen.regenerate_positioning_bundle("never-generated")


