class TestCardsPerspectiveFallback:
    """F3: when an opponent's positioning data exists only under a
    non-standalone perspective (e.g., ``perspective_team_id = 99``,
    the member team's perspective), the bundle's cards section MUST
    render that data via prefer-then-fallback. Prior to remediation the
    bundle hard-filtered on ``perspective_team_id = team_id`` and
    silently dropped the cards section; the call sheet + prep page
    already used the prefer-then-fallback pattern, so the bug was a
    user-visible asymmetry between the three sections."""

    def test_cards_section_renders_when_only_opponent_perspective(
        self, conn,
    ):
        """Repro per Codex F3: seed aggregates + batter rows ONLY under
        ``perspective_team_id = 99`` (the LSB member team's
        perspective) and assert the rendered bundle still shows the
        batter's outlier zone in the cards section."""
        # Standard fixture except perspective_team_id is forced to 99
        # (the member team), simulating data sourced via the member's
        # boxscore-scouting view of the opponent.
        for p in COVERED_POSITIONS:
            conn.execute(
                """
                INSERT INTO team_position_aggregate (
                    team_id, season_id, perspective_team_id, position,
                    star_x, star_y, bip_count, is_low_confidence
                ) VALUES (1, ?, 99, ?, 160.0, 200.0, 60, 0)
                """,
                (_SEASON, p),
            )
        _seed_player(conn, "p1", "Hank", "Ramirez")
        _seed_roster(conn, "p1", "7")
        _seed_batter_row(
            conn, player_id="p1", position="LF",
            zone_id="A", direction_deviation=-1, depth_deviation=-1,
            perspective_team_id=99,
        )
        for p in ("CF", "RF", "3B", "SS", "2B"):
            _seed_batter_row(
                conn, player_id="p1", position=p,
                perspective_team_id=99,
            )
        conn.commit()

        html = generate_positioning_bundle(
            conn, "opp-bears", _SEASON,
            opponent_name="Opp Bears",
            through_date="Apr 12", game_count=12,
        )
        # Cards section is present (the section wrapper renders even
        # in the zero-coverage state, so this alone proves nothing).
        assert "positioning-cards-sheet" in html
        # The cards section must actually render the batter -- the
        # prior bug left the section in the "no outliers" empty state
        # because _query_cards_positioning_rows returned [].
        assert "RAMIREZ" in html

    def test_choose_perspective_prefers_standalone(self, conn):
        """When BOTH standalone (perspective=team_id=1) AND non-
        standalone (perspective=99) rows exist, the chosen perspective
        MUST be the standalone one to match the sibling render helpers."""
        from src.reports.positioning_bundle import _choose_perspective_team_id

        for p in COVERED_POSITIONS:
            conn.execute(
                """
                INSERT INTO team_position_aggregate (
                    team_id, season_id, perspective_team_id, position,
                    star_x, star_y, bip_count, is_low_confidence
                ) VALUES (1, ?, 1, ?, 160.0, 200.0, 60, 0)
                """,
                (_SEASON, p),
            )
            conn.execute(
                """
                INSERT INTO team_position_aggregate (
                    team_id, season_id, perspective_team_id, position,
                    star_x, star_y, bip_count, is_low_confidence
                ) VALUES (1, ?, 99, ?, 160.0, 200.0, 60, 0)
                """,
                (_SEASON, p),
            )
        conn.commit()
        assert _choose_perspective_team_id(conn, 1, _SEASON) == 1

    def test_choose_perspective_falls_back_when_standalone_absent(
        self, conn,
    ):
        """When ONLY a non-standalone perspective exists, fall back to
        it (return ``99``) rather than returning None."""
        from src.reports.positioning_bundle import _choose_perspective_team_id

        for p in COVERED_POSITIONS:
            conn.execute(
                """
                INSERT INTO team_position_aggregate (
                    team_id, season_id, perspective_team_id, position,
                    star_x, star_y, bip_count, is_low_confidence
                ) VALUES (1, ?, 99, ?, 160.0, 200.0, 60, 0)
                """,
                (_SEASON, p),
            )
        conn.commit()
        assert _choose_perspective_team_id(conn, 1, _SEASON) == 99

    def test_choose_perspective_returns_none_when_no_aggregates(self, conn):
        from src.reports.positioning_bundle import _choose_perspective_team_id
        assert _choose_perspective_team_id(conn, 1, _SEASON) is None


