class TestOpponentContextPayload:
    """F2 (b): the `_build_opponent_context` helper builds the page-4
    slot-3 + slot-4 template-context payload per UXD's locked spec."""

    def _seed_games(self, conn, *, scored: int = 32, allowed: int = 14):
        """Seed 5 completed games for team_id=1 so the runs-per-game +
        record queries have data. Per-game scoring distributes the
        ``scored`` / ``allowed`` totals across 5 games."""
        # Distribute scored = 32, allowed = 14 -> 6.4 / 2.8 per game.
        per_game = [
            (1, 99, 8, 2),
            (99, 1, 5, 6),
            (1, 99, 7, 4),
            (99, 1, 3, 8),
            (1, 99, 3, 0),
        ]
        for idx, (home, away, hs, as_) in enumerate(per_game):
            conn.execute(
                """
                INSERT INTO games (
                    game_id, season_id, home_team_id, away_team_id,
                    home_score, away_score, game_date
                ) VALUES (?, ?, ?, ?, ?, ?, ?)
                """,
                (f"g{idx}", _SEASON, home, away, hs, as_,
                 f"2026-03-{idx + 1:02d}"),
            )
        conn.commit()

    def test_full_tier(self, conn):
        from src.reports.positioning_bundle import _build_opponent_context
        _seed_full_opponent(conn)  # team aggregates bip_count=60, low_conf=0
        self._seed_games(conn)
        ctx = _build_opponent_context(
            conn,
            team_id=1, season_id=_SEASON, perspective_team_id=1,
            game_count=12, today="2026-05-01",
        )
        assert "Full" in ctx["opponent_context_tier_line"]
        assert ("outlier markers and density background"
                in ctx["opponent_context_tier_line"])

