    def test_stats_list_has_four_rows_in_fixed_order(self, conn):
        from src.reports.positioning_bundle import _build_opponent_context
        _seed_full_opponent(conn)
        self._seed_games(conn)
        ctx = _build_opponent_context(
            conn,
            team_id=1, season_id=_SEASON, perspective_team_id=1,
            game_count=12, today="2026-05-01",
        )
        stats = ctx["opponent_context_stats"]
        assert len(stats) == 4
        labels = [s["label"] for s in stats]
        assert labels == [
            "Record", "Runs / game", "Runs allowed / game", "Team BIPs",
        ]
        # Record: team 1 wins all 5 (home-wins: g0, g2, g4 with 8>2,
        # 7>4, 3>0; away-wins: g1, g3 with 6>5, 8>3).
        assert stats[0]["value"] == "5–0"
        # Runs scored avg = (8+6+7+8+3)/5 = 6.4
        assert stats[1]["value"] == "6.4"
        # Runs allowed avg = (2+5+4+3+0)/5 = 2.8
        assert stats[2]["value"] == "2.8"
        # Team BIPs from any aggregate row = 60.
        assert stats[3]["value"] == "60"

