class TestBundleThreadsCompassKeyAndOpponentContext:
    """F2 (c): the rendered bundle HTML includes the compass-key SVG
    body content AND the 4 opponent-context stat rows."""

    def test_bundle_renders_compass_key_letters(self, conn):
        _seed_full_opponent(conn)
        html = generate_positioning_bundle(
            conn, "opp-bears", _SEASON,
            opponent_name="Opp Bears",
            through_date="Apr 12", game_count=12,
        )
        # Slot 3's SVG body content: every compass letter A-H must
        # appear inside a <text> element in the slot-3 SVG. (Many of
        # those letters may also appear elsewhere in zone-letter cells
        # in the call sheet / cards, so we scope to the slot div and
        # its SVG body specifically.)
        slot3_start = html.find(
            'class="positioning-card compass-key"',
        )
        assert slot3_start > 0, "compass-key slot div not rendered"
        svg_start = html.find("<svg", slot3_start)
        svg_end = html.find("</svg>", svg_start) + len("</svg>")
        assert svg_start > slot3_start and svg_end > svg_start, (
            "compass-key slot must contain an inline <svg> body"
        )
        svg_body = html[svg_start:svg_end]
        for letter in "ABCDEFGH":
            assert f">{letter}<" in svg_body, (
                f"compass-key slot SVG missing letter {letter}"
            )
        for axis in ("DEEP", "IN", "LEFT", "RIGHT"):
            assert f">{axis}<" in svg_body, (
                f"compass-key slot SVG missing axis label {axis}"
            )

